def parse_rel(rel):
    rel = rel.lower().strip()
    m = re.match(r'(\d+)\s+(second|minute|hour|day|week|month|year)s?\s+ago', rel)
    if m:
        val, unit = int(m.group(1)), m.group(2)
        d = timedelta()
        if unit == 'day': d = timedelta(days=val)
        elif unit == 'week': d = timedelta(weeks=val)
        elif unit == 'month': d = timedelta(days=val*30)
        elif unit == 'year': d = timedelta(days=val*365)
        elif unit == 'hour': d = timedelta(hours=val)
        elif unit == 'minute': d = timedelta(minutes=val)
        elif unit == 'second': d = timedelta(seconds=val)
        return REF - d
    return None

